set -eu
cd "$HOME/native-managed-broker-effects-3b-v1"
python3 - <<'PY'
import pathlib,os,json,hashlib,base64
root=pathlib.Path.cwd()
found=[]
for p in pathlib.Path('/proc').iterdir():
 if not p.name.isdigit() or int(p.name) in (os.getpid(),os.getppid()): continue
 try:
  cwd=os.readlink(p/'cwd')
  exe=os.readlink(p/'exe')
  cmd=(p/'cmdline').read_bytes().replace(b'\0',b' ').decode(errors='replace')
  if cwd.startswith(str(root)) or exe.startswith(str(root)) or str(root) in cmd: found.append({'pid':int(p.name),'cwd':cwd,'exe':exe,'args':cmd[:2000]})
 except OSError: pass
facts={'matching_owned_build_processes':found,'old_guest_log_sha256':hashlib.sha256((root/'evidence/guest-build.log').read_bytes()).hexdigest(),'old_guest_exit_file_exists':(root/'evidence/guest-build.exit').exists(),'interpretation':'single process snapshot, not full kernel return; r74 runner-restart outcome Unknown'}
(root/'evidence/interrupted-process-snapshot.json').write_text(json.dumps(facts,indent=2))
print(json.dumps(facts))
assert not found,'preserve actual active owned compiler; no dependent build'
p=root/'source/docs/research/measurements/managed-broker-effects/resume-artifacts.sh'
assert not p.exists()
p.write_bytes(base64.b64decode(''))
PY
bash source/docs/research/measurements/managed-broker-effects/resume-artifacts.sh
